"""K-way merge utilities: lazy heap-based merge vs naive concat+sort."""

import heapq


def merge_heap(iterators):
    """Lazily merge k sorted iterators into one sorted iterator.

    Tie-breaks equal keys by iterator index (stable). Never materializes
    the inputs; elements are pulled lazily from each source iterator.
    """
    iterators = [iter(it) for it in iterators]
    # Heap of (key, iterator_index, value, iterator)
    heap = []
    for idx, it in enumerate(iterators):
        try:
            first = next(it)
        except StopIteration:
            continue
        heapq.heappush(heap, (first[0], idx, first[1], it))
    while heap:
        key, idx, val, it = heapq.heappop(heap)
        yield key, val
        try:
            nxt = next(it)
        except StopIteration:
            continue
        heapq.heappush(heap, (nxt[0], idx, nxt[1], it))


def merge_naive(lists):
    """Merge by concatenating all lists and sorting. Fully eager."""
    combined = []
    for lst in lists:
        combined.extend(lst)
    combined.sort(key=lambda kv: kv[0])
    return iter(combined)

