import heapq


class _LazyIter:
    """Wraps an iterable so that iter() is only called when first advanced."""

    __slots__ = ("src", "it")

    def __init__(self, src):
        self.src = src
        self.it = None

    def __iter__(self):
        return self

    def __next__(self):
        if self.it is None:
            self.it = iter(self.src)
        return next(self.it)


