def test_lazy_never_materializes():
    class Explodes:
        def __iter__(self):
            raise AssertionError("input was materialized")

        def __next__(self):
            raise AssertionError

    # Pass the raw iterable; merge_heap must not call iter() on it
    # until it actually needs a value from that source.
    it = merge_heap([[(0, 0)], Explodes()])
    # Pulling only the first element must not touch the other iterator.
    assert next(it) == (0, 0)

